# Let me try yet another hypothesis
# What if after horizontal fill, we need to do additional vertical filling 
# only for columns that have >= 2 foreground pixels?

grid = [
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 9, 9, 6, 9, 6, 6, 6, 6],
    [6, 6, 6, 6, 9, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 9, 9, 9],
    [6, 6, 6, 6, 9, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 9],
    [6, 6, 6, 6, 9, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 9, 6, 6, 6, 9, 9, 6, 9],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6]
]

rows = len(grid)
cols = len(grid[0])
output = [[6]*cols for _ in range(rows)]

# First, copy original foreground
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 9:
            output[r][c] = 9

# Then fill horizontal gaps
for r in range(rows):
    fg_positions = sorted([c for c in range(cols) if grid[r][c] == 9])
    for i in range(len(fg_positions) - 1):
        left, right = fg_positions[i], fg_positions[i+1]
        for c in range(left+1, right):
            if grid[r][c] == 6:
                output[r][c] = 9

# Finally, fill vertical gaps for columns with >= 2 foreground
for c in range(cols):
    # Count original foreground in this column
    orig_fg_count = sum(1 for r in range(rows) if grid[r][c] == 9)

    if orig_fg_count >= 2:
        fg_positions = sorted([r for r in range(rows) if grid[r][c] == 9 or output[r][c] == 9])
        for i in range(len(fg_positions) - 1):
            top, bottom = fg_positions[i], fg_positions[i+1]
            for r in range(top+1, bottom):
                if output[r][c] == 6:
                    output[r][c] = 9

print("Output:")
for row in output:
    print(' '.join(str(x) for x in row))

